    {
      "@type": "Question",
      "name": "Does FDA registered mean FDA approved?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Registration is largely an administrative listing. FDA cleared and FDA approved describe different regulatory routes with different evidence requirements. Suppliers describe themselves as registered far more often than cleared, and the gap is where buyers are misled."
      }
    },
    {
      "@type": "Question",
      "name": "Who can issue a CE mark?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For lower risk products the manufacturer can declare conformity itself. Higher risk products require an independent notified body. Ask which route was used and, for higher risk items, which notified body issued the certificate."
      }
    },
    {
      "@type": "Question",
      "name": "What do these certifications not tell me?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "None of them guarantee that the consignment you receive matches the sample you approved. Batch consistency is answered by the certificate of analysis for the specific lot and by verification before shipment."
      }
    }
  ]
